BEGIN;UPDATE public.engine_tournament_leases SET heartbeat_at=clock_timestamp() WHERE tournament_id='88fd351e-52e4-5765-a39b-3eef190fb755';CREATE FUNCTION pg_temp.refuse_second_assignment() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN IF NEW.user_id='49834dba-2e57-505b-8f1d-0cc1e70bee19' AND OLD.left_at IS NOT NULL AND NEW.left_at IS NULL THEN RAISE EXCEPTION 'isolated_native_assignment_fault' USING ERRCODE='P0404';END IF;RETURN NEW;END;$f$;CREATE TRIGGER zzz_qualification_fault BEFORE UPDATE ON public.table_seats FOR EACH ROW EXECUTE FUNCTION pg_temp.refuse_second_assignment();DO $fault$ DECLARE before_image jsonb; after_image jsonb;caught boolean:=false;BEGIN SELECT jsonb_build_object('chairs',(SELECT jsonb_agg(to_jsonb(s) ORDER BY id) FROM public.table_seats s WHERE table_id='5df641f6-51a4-5ab7-87cc-8ef63d4e859b'),'rosters',(SELECT jsonb_agg(to_jsonb(p) ORDER BY id) FROM public.tournament_players p WHERE tournament_id='88fd351e-52e4-5765-a39b-3eef190fb755'),'debits',(SELECT jsonb_agg(to_jsonb(w) ORDER BY id) FROM public.wallet_transactions w),'funds',(SELECT jsonb_agg(to_jsonb(f) ORDER BY id) FROM public.tournament_participant_funding_receipts f)) INTO before_image;BEGIN PERFORM smarter_private.continue_retired_undealt_paid_entry('88fd351e-52e4-5765-a39b-3eef190fb755');EXCEPTION WHEN SQLSTATE 'P0404' THEN IF SQLERRM<>'isolated_native_assignment_fault' THEN RAISE;END IF;caught:=true;END;SELECT jsonb_build_object('chairs',(SELECT jsonb_agg(to_jsonb(s) ORDER BY id) FROM public.table_seats s WHERE table_id='5df641f6-51a4-5ab7-87cc-8ef63d4e859b'),'rosters',(SELECT jsonb_agg(to_jsonb(p) ORDER BY id) FROM public.tournament_players p WHERE tournament_id='88fd351e-52e4-5765-a39b-3eef190fb755'),'debits',(SELECT jsonb_agg(to_jsonb(w) ORDER BY id) FROM public.wallet_transactions w),'funds',(SELECT jsonb_agg(to_jsonb(f) ORDER BY id) FROM public.tournament_participant_funding_receipts f)) INTO after_image;IF NOT caught OR before_image IS DISTINCT FROM after_image OR EXISTS(SELECT 1 FROM smarter_private.retirement_undealt_paid_entry_restorations) THEN RAISE EXCEPTION 'whole original assignment rollback failed';END IF;RAISE NOTICE 'NATIVE_WHOLE_OWNER_ROLLBACK_PASS';END;$fault$;ROLLBACK;
